struct string_buf
{
  unsigned long long *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

  int compare(const string_buf &buf) const
  {
    int i;
    const char *a = reinterpret_cast<const char *>(data);
    const char *b = reinterpret_cast<const char *>(buf.data);
    int cmp_len = char_length < buf.char_length ? char_length : buf.char_length;
    for (i = 0; i < cmp_len; ++i)
    {
      if (a[i] == b[i])
        continue;
      if (b[i] > a[i])
        return 1;
      if (b[i] < a[i])
        return -1;
    }
    if (buf.char_length > char_length)
      return 1;
    if (buf.char_length < char_length)
      return -1;
    return 0;
  }
};

struct stringx
{
  char *chars;
  string_buf *my_buf;
};

inline bool operator<(const stringx &lhs, const stringx &rhs)
{
  return lhs.my_buf->compare(*rhs.my_buf) == 1;
}

